namespace Scheduling;

/// <summary>Finds the first calendar slot that fits a required duration.</summary>
public sealed class SlotFinder
{
    public Slot? FindFirstFit(Resource resource, TimeSpan duration, DateTime notBefore)
    {
        if (resource.Calendar.Count == 0 || duration <= TimeSpan.Zero)
            return null;

        foreach (var slot in resource.Calendar)
        {
            if (IsSuitable(slot, duration, notBefore))
                return slot;
        }

        return null;
    }

    private static bool IsSuitable(Slot slot, TimeSpan duration, DateTime notBefore)
    {
        if (slot.Start < notBefore)
            return false;

        if (slot.End - slot.Start < duration)
            return false;

        return IsWithinWorkingHours(slot);
    }

    private static bool IsWithinWorkingHours(Slot slot)
    {
        return slot.Start.Hour >= 8
            && slot.Start.Hour <= 18
            && slot.End.Hour <= 20;
    }
}
